:root {
    --color-primary: #6366f1;
    --color-primary-dark: #4f46e5;
    --color-primary-light: #818cf8;
    --bg-primary: #0f172a;
    --bg-secondary: #1e293b;
    --bg-tertiary: #334155;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --text-tertiary: #94a3b8;
    --border-color: #334155;
    --border-color-light: #475569;
    --success: #10b981;
    --error: #ef4444;
    --focus-outline: #818cf8;
}

/* Global Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    background: linear-gradient(135deg, var(--bg-primary) 0%, #1a2332 100%);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
}

main {
    padding: 2rem 1rem;
}

/* Quiz Container */
.quiz-container {
    max-width: 800px;
    margin: 0 auto;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
}

.quiz-wrapper {
    width: 100%;
    background: var(--bg-secondary);
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
    overflow: hidden;
    border: 1px solid var(--border-color);
}

/* Header */
header {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    padding: 2.5rem 2rem;
    text-align: center;
}

header h1 {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    letter-spacing: -0.5px;
}

.subtitle {
    font-size: 1rem;
    opacity: 0.95;
    font-weight: 400;
}

/* Form Styles */
.quiz-form {
    padding: 2rem;
}

.form-field {
    margin-bottom: 2.5rem;
    padding: 1.5rem;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    transition: all 0.3s ease;
}

.form-field:hover {
    border-color: var(--border-color-light);
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.1);
}

.question-header {
    margin-bottom: 1rem;
}

.question-header h2 {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--color-primary-light);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.5rem;
}

.question-title {
    display: block;
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text-primary);
    margin: 0;
    cursor: pointer;
}

/* Help Text */
.help-text {
    font-size: 0.875rem;
    color: var(--text-tertiary);
    margin: 0.75rem 0 1.25rem 0;
    font-style: italic;
}

/* Fieldset and Legend */
fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    display: block;
    width: 100%;
    padding: 0;
    margin: 0;
    border: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Checkbox Group */
.checkbox-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 0.75rem 1rem;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    transition: all 0.2s ease;
    position: relative;
}

.checkbox-label:hover {
    border-color: var(--color-primary-light);
    background: rgba(99, 102, 241, 0.05);
}

.checkbox-label:has(input:focus) {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

.checkbox-label:has(input:checked) {
    background: rgba(99, 102, 241, 0.1);
    border-color: var(--color-primary);
}

/* Hidden Checkbox */
.checkbox-label input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    width: 100%;
    height: 100%;
    margin: 0;
}

/* Custom Checkbox */
.checkbox-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    min-width: 20px;
    border: 2px solid var(--border-color-light);
    border-radius: 4px;
    background: var(--bg-tertiary);
    transition: all 0.2s ease;
    margin-right: 0.75rem;
}

.checkbox-label:has(input:checked) .checkbox-custom {
    background: var(--color-primary);
    border-color: var(--color-primary);
    box-shadow: 0 0 12px rgba(99, 102, 241, 0.4);
}

.checkbox-label:has(input:checked) .checkbox-custom::after {
    content: '✓';
    color: white;
    font-size: 14px;
    font-weight: bold;
}

.label-text {
    font-size: 1rem;
    font-weight: 500;
    color: var(--text-primary);
}

/* Submit Button */
.submit-btn {
    width: 100%;
    padding: 1rem 2rem;
    font-size: 1rem;
    font-weight: 600;
    color: white;
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 1.5rem;
    box-shadow: 0 4px 15px rgba(99, 102, 241, 0.3);
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(99, 102, 241, 0.4);
}

.submit-btn:active {
    transform: translateY(0);
}

.submit-btn:focus {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

.submit-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Results Container */
.results-container {
    padding: 2rem;
    text-align: center;
}

.results-container h2 {
    font-size: 2rem;
    margin-bottom: 1.5rem;
    background: linear-gradient(135deg, var(--color-primary), var(--color-primary-light));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.results-summary {
    margin: 2rem 0;
    padding: 1.5rem;
    background: var(--bg-primary);
    border-radius: 8px;
    border: 1px solid var(--border-color);
    text-align: left;
}

.results-summary p {
    margin: 0.75rem 0;
    font-size: 1rem;
}

.reset-btn {
    padding: 0.75rem 2rem;
    font-size: 1rem;
    font-weight: 600;
    color: white;
    background: var(--color-primary);
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 1.5rem;
}

.reset-btn:hover {
    background: var(--color-primary-dark);
    transform: translateY(-2px);
}

.reset-btn:focus {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

/* Responsive Design */
@media (max-width: 640px) {
    .quiz-container {
        padding: 1rem;
    }

    header {
        padding: 2rem 1.5rem;
    }

    header h1 {
        font-size: 1.5rem;
    }

    .subtitle {
        font-size: 0.9rem;
    }

    .quiz-form {
        padding: 1.5rem;
    }

    .form-field {
        padding: 1rem;
        margin-bottom: 2rem;
    }

    .question-title {
        font-size: 1.125rem;
    }
}

/* High Contrast / Forced Colors */
@media (forced-colors: active) {
    .checkbox-custom {
        border: 2px solid ButtonBorder;
        background: Canvas;
    }

    .checkbox-label:has(input:checked) .checkbox-custom {
        background: Highlight;
        border-color: Highlight;
    }

    .submit-btn,
    .reset-btn {
        border: 2px solid ButtonBorder;
    }

    .form-field {
        border-color: CanvasText;
    }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
