const resultsContainer = document.getElementById('results');
const resultsSummary = document.getElementById('resultsSummary');

// Correct answers for each question
const correctAnswers = {
    q1: ['Java', 'Python', 'C++'], // OOP languages
    q2: ['JavaScript', 'WebAssembly'], // Web browser languages
    q3: ['TypeScript', 'Rust'] // Statically typed
};

// Handle form submission
quizForm.addEventListener('submit', function (e) {
    e.preventDefault();
    evaluateQuiz();
});

function evaluateQuiz() {
    const results = {};
    let totalCorrect = 0;

    // Get selected answers for each question
    for (const [question, correct] of Object.entries(correctAnswers)) {
        const checkboxes = document.querySelectorAll(`input[name="${question}"]:checked`);
        const selected = Array.from(checkboxes).map(cb => cb.value);

        // Check if selected answers match correct answers
        const isCorrect = areArraysEqual(selected.sort(), correct.sort());
        results[question] = {
            selected: selected,
            correct: correct,
            isCorrect: isCorrect
        };

        if (isCorrect) {
            totalCorrect++;
        }
    }

    displayResults(results, totalCorrect);
}

function areArraysEqual(arr1, arr2) {
    if (arr1.length !== arr2.length) return false;
    return arr1.every((val, idx) => val === arr2[idx]);
}

function displayResults(results, totalCorrect) {
    // Hide form and show results
    quizForm.hidden = true;
    resultsContainer.hidden = false;

    // Calculate score
    const score = (totalCorrect / 3) * 100;
    const scoreMessage = getScoreMessage(score);

    // Build results HTML
    let resultsHTML = `
        <p><strong>Your Score: ${score.toFixed(0)}%</strong></p>
        <p>${scoreMessage}</p>
        <hr style="border: 1px solid var(--border-color); margin: 1rem 0;">
    `;

    // Show details for each question
    Object.entries(results).forEach(([question, result], index) => {
        const questionNum = index + 1;
        const status = result.isCorrect ? '✓ Correct' : '✗ Incorrect';
        const statusClass = result.isCorrect ? 'correct' : 'incorrect';

        resultsHTML += `
            <div style="margin-bottom: 1.5rem; padding-bottom: 1rem; border-bottom: 1px solid var(--border-color);">
                <p><strong>Question ${questionNum}</strong> <span style="color: ${result.isCorrect ? '#10b981' : '#ef4444'}; font-weight: 600;">${status}</span></p>
                <p style="color: var(--text-secondary); margin-top: 0.5rem;">
                    <strong>Your answer:</strong> ${result.selected.length > 0 ? result.selected.join(', ') : 'No answer selected'}
                </p>
                <p style="color: var(--text-secondary);">
                    <strong>Correct answer:</strong> ${result.correct.join(', ')}
                </p>
            </div>
        `;
    });

    resultsSummary.innerHTML = resultsHTML;
}

function getScoreMessage(score) {
    if (score === 100) {
        return 'Perfect score! You are a programming languages expert! 🎉';
    } else if (score >= 66) {
        return 'Great job! You have solid knowledge of programming languages! 👏';
    } else if (score >= 33) {
        return 'Good effort! Keep learning about programming languages. 📚';
    } else {
        return 'Keep practicing! Learn more about different programming languages. 💪';
    }
}
